Looking at the `kernel_atax` function, I need to:

1. Add HLS INTERFACE pragmas for all pointer arguments and scalar return
2. Pipeline the innermost loops
3. Partition arrays for parallel access
4. Keep the algorithm unchanged

Key observations:
- The inner loops over `j` (size N=124) access `A[i][j]`, `x[j]`, `y[j]` - these need pipelining
- `tmp` array (size M=116) and `x`/`y` arrays (size N=124) benefit from array partitioning
- The two inner `j` loops have a loop-carried dependency on `tmp[i]` and `y[j]` respectively, but since `tmp[i]` is a scalar accumulation within the first loop and `y[j]` accumulates across `i` iterations, we need to be careful
- For the inner `j` loops, pipelining with II=1 works for the first loop (scalar reduction into `tmp[i]`), and the second loop has a loop-carried dependency on `y[j]` that limits II

```cpp
#include "atax.h"

void kernel_atax(
    double A[M + 0][N + 0],
    double x[N + 0],
    double y[N + 0],
    double tmp[M + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=tmp    bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers to avoid repeated global memory accesses
    double l_A[M][N];
    double l_x[N];
    double l_y[N];
    double l_tmp[M];

    #pragma HLS ARRAY_PARTITION variable=l_x   cyclic factor=8 dim=1
    #pragma HLS ARRAY_PARTITION variable=l_y   cyclic factor=8 dim=1
    #pragma HLS ARRAY_PARTITION variable=l_tmp cyclic factor=8 dim=1
    #pragma HLS ARRAY_PARTITION variable=l_A   cyclic factor=8 dim=2

    // Load x from global memory
    load_x: for (int j = 0; j < N; j++) {
        #pragma HLS PIPELINE II=1
        l_x[j] = x[j];
    }

    // Load A from global memory
    load_A: for (int i = 0; i < M; i++) {
        for (int j = 0; j < N; j++) {
            #pragma HLS PIPELINE II=1
            l_A[i][j] = A[i][j];
        }
    }

    // Initialize y
    init_y: for (int i = 0; i < N; i++) {
        #pragma HLS PIPELINE II=1
        l_y[i] = 0.0;
    }

    // Main computation
    for (int i = 0; i < M; i++) {
        double tmp_i = 0.0;

        // First inner loop: tmp[i] = sum_j A[i][j] * x[j]
        loop_tmp: for (int j = 0; j < N; j++) {
            #pragma HLS PIPELINE II=1
            tmp_i += l_A[i][j] * l_x[j];
        }
        l_tmp[i] = tmp_i;

        // Second inner loop: y[j] += A[i][j] * tmp[i]
        loop_y: for (int j = 0; j < N; j++) {
            #pragma HLS PIPELINE II=1
            l_y[j] += l_A[i][j] * tmp_i;
        }
    }

    // Write back y to global memory
    store_y: for (int j = 0; j < N; j++) {
        #pragma HLS PIPELINE II=1
        y[j] = l_y[j];
    }

    // Write back tmp to global memory
    store_tmp: for (int i = 0; i < M; i++) {
        #pragma HLS PIPELINE II=1
        tmp[i] = l_tmp[i];
    }
}
```

Looking at the current code, it already has local buffers but loads the entire A matrix (M×N = 116×124 doubles = ~115KB) at once. True tiling means processing A in row-tiles, so each tile fits better in local memory and we get better reuse patterns. I'll tile over rows of A (tile size = TILE_M rows), processing each tile through load/compute/store phases.

```cpp
#include "atax.h"

// Tile size for rows of A
#define TILE_M 16

static void load_x_buf(double x[N], double l_x[N]) {
    load_x: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        l_x[j] = x[j];
    }
}

static void load_A_tile(double A[M][N], double l_A[TILE_M][N],
                        int row_start, int rows) {
    load_A: for (int i = 0; i < rows; i++) {
        for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            l_A[i][j] = A[row_start + i][j];
        }
    }
}

static void compute_tile(double l_A[TILE_M][N], double l_x[N],
                         double l_tmp_tile[TILE_M], double l_y[N],
                         int rows) {
    compute_rows: for (int i = 0; i < rows; i++) {
        double tmp_i = 0.0;

        // Compute tmp[i] = sum_j A[i][j] * x[j]
        loop_tmp: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            tmp_i += l_A[i][j] * l_x[j];
        }
        l_tmp_tile[i] = tmp_i;

        // Accumulate y[j] += A[i][j] * tmp[i]
        loop_y: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            l_y[j] += l_A[i][j] * tmp_i;
        }
    }
}

static void store_tmp_tile(double tmp[M], double l_tmp_tile[TILE_M],
                           int row_start, int rows) {
    store_tmp: for (int i = 0; i < rows; i++) {
#pragma HLS PIPELINE II=1
        tmp[row_start + i] = l_tmp_tile[i];
    }
}

static void store_y_buf(double y[N], double l_y[N]) {
    store_y: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        y[j] = l_y[j];
    }
}

void kernel_atax(
    double A[M + 0][N + 0],
    double x[N + 0],
    double y[N + 0],
    double tmp[M + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A      bundle=control
#pragma HLS INTERFACE s_axilite port=x      bundle=control
#pragma HLS INTERFACE s_axilite port=y      bundle=control
#pragma HLS INTERFACE s_axilite port=tmp    bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local buffers
    double l_x[N];
    double l_y[N];
    // Tile buffers — only TILE_M rows at a time instead of all M rows
    double l_A[TILE_M][N];
    double l_tmp_tile[TILE_M];

#pragma HLS ARRAY_PARTITION variable=l_x        cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_y        cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_tmp_tile cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=l_A        cyclic factor=8 dim=2

    // Phase 1: Load x into local buffer (reused across all tiles)
    load_x_buf(x, l_x);

    // Phase 2: Initialize y accumulator
    init_y: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        l_y[j] = 0.0;
    }

    // Phase 3: Process A in row-tiles
    tile_loop: for (int row_start = 0; row_start < M; row_start += TILE_M) {
        // Number of rows in this tile (handle boundary)
        int rows = (row_start + TILE_M <= M) ? TILE_M : (M - row_start);

        // Load: bring current tile of A into local buffer
        load_A_tile(A, l_A, row_start, rows);

        // Compute: work entirely on local buffers
        compute_tile(l_A, l_x, l_tmp_tile, l_y, rows);

        // Store: write tmp results for this tile back to global memory
        store_tmp_tile(tmp, l_tmp_tile, row_start, rows);
    }

    // Phase 4: Store accumulated y back to global memory
    store_y_buf(y, l_y);
}
```

**Key tiling changes made:**
1. **Tile buffer `l_A[TILE_M][N]`** instead of `l_A[M][N]` — reduces local memory from 116×124 to 16×124 doubles, saving ~86% of the on-chip BRAM/FF used for A
2. **Row-tiled loop** over A with `TILE_M=16` rows per tile — each tile is loaded, computed, and tmp stored before moving to the next
3. **`l_y[N]` is kept across tiles** to correctly accumulate contributions from all rows
4. **`l_x[N]` loaded once** and reused across all tiles (exploits temporal reuse)
5. **Clear load/compute/store phases** within each tile iteration, with `store_tmp_tile` writing partial tmp results after each tile

Looking at the current code, I need to add pipeline optimizations to the innermost compute loops, add appropriate array partitioning, and add dependence pragmas where needed.

Key observations:
1. `loop_tmp` has a loop-carried dependency on `tmp_i` (floating-point reduction) - need `DEPENDENCE inter false` since it's within the same loop iteration
2. `loop_y` accumulates into `l_y[j]` - needs `DEPENDENCE inter false` since each `j` is independent
3. Variable-bound loops in `compute_tile`, `load_A_tile`, `store_tmp_tile` need `LOOP_TRIPCOUNT`
4. Local arrays inside `compute_tile` need partitioning to allow parallel access when pipelined

```cpp
