#pragma HLS PIPELINE II=1
        l_y[j] = 0.0;
    }

    // Phase 3: Process A in row-tiles
    tile_loop: for (int row_start = 0; row_start < M; row_start += TILE_M) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=(M+TILE_M-1)/TILE_M
