#define LARGE_BUS 512
typedef ap_uint<LARGE_BUS> MARS_WIDE_BUS_TYPE;
#define WIDE_BUS_BYTES (LARGE_BUS / 8)
#define DOUBLES_PER_WIDE (WIDE_BUS_BYTES / sizeof(double))

// Helper: read doubles from wide bus pointer into local array
static void memcpy_wide_bus_read_double(double* dst,
                                        const MARS_WIDE_BUS_TYPE* src,
                                        size_t byte_offset,
                                        size_t byte_len) {
    const int dpw = DOUBLES_PER_WIDE; // 8 doubles per 512-bit word
    size_t word_offset = byte_offset / WIDE_BUS_BYTES;
    size_t num_doubles = byte_len / sizeof(double);
    size_t num_words   = (num_doubles + dpw - 1) / dpw;

    read_wide: for (size_t w = 0; w < num_words; w++) {
#pragma HLS PIPELINE II=1
        MARS_WIDE_BUS_TYPE wide_val = src[word_offset + w];
        size_t base = w * dpw;
        for (int d = 0; d < dpw; d++) {
#pragma HLS UNROLL
            if (base + d < num_doubles) {
                ap_uint<64> bits = wide_val.range(64*(d+1)-1, 64*d);
                double val;
                memcpy(&val, &bits, sizeof(double));
                dst[base + d] = val;
            }
        }
    }
}

// Helper: write doubles from local array into wide bus pointer
static void memcpy_wide_bus_write_double(MARS_WIDE_BUS_TYPE* dst,
                                         const double* src,
                                         size_t byte_offset,
                                         size_t byte_len) {
    const int dpw = DOUBLES_PER_WIDE;
    size_t word_offset = byte_offset / WIDE_BUS_BYTES;
    size_t num_doubles = byte_len / sizeof(double);
    size_t num_words   = (num_doubles + dpw - 1) / dpw;

    write_wide: for (size_t w = 0; w < num_words; w++) {
#pragma HLS PIPELINE II=1
        MARS_WIDE_BUS_TYPE wide_val = 0;
        size_t base = w * dpw;
        for (int d = 0; d < dpw; d++) {
#pragma HLS UNROLL
            ap_uint<64> bits = 0;
            if (base + d < num_doubles) {
                double val = src[base + d];
                memcpy(&bits, &val, sizeof(double));
            }
            wide_val.range(64*(d+1)-1, 64*d) = bits;
        }
        dst[word_offset + w] = wide_val;
    }
